import type { ScoreRow } from "./sheets";
import { MODEL_ODDS } from "./playoff-odds-model";

// Playoff odds by record. Two sources:
//
// 1. MODEL_ODDS — generated by scripts/build-playoff-odds.mjs. A season
//    simulator calibrated to Roster Audit's published "after Week 7" table,
//    then run in ITTWA's exact format (3-team divisions, 4 division winners +
//    2 wild cards, top 2 byes, 14-week regular season) to extrapolate every
//    other week. Values are percentages.
// 2. ITTWA history — what actually happened to teams at each record in past
//    ITTWA seasons, computed live from the Scores sheet. Small samples; shown
//    as "n of m" next to the model so nobody over-reads it.

export const ODDS_OUTCOMES = ["playoffs", "bye", "semis", "final", "title"] as const;
export type OddsOutcome = (typeof ODDS_OUTCOMES)[number];
export type Odds = Record<OddsOutcome, number>;

export const ODDS_LABELS: Record<OddsOutcome, string> = {
  playoffs: "Playoffs",
  bye: "Bye",
  semis: "Semis",
  final: "Final",
  title: "Title",
};

/** Weeks the model covers: after Week 1 through after Week 13 (one game left). */
export const MODEL_WEEKS = Object.keys(MODEL_ODDS).map(Number).sort((a, b) => a - b);

function tupleToOdds(t: readonly number[]): Odds {
  return { playoffs: t[0], bye: t[1], semis: t[2], final: t[3], title: t[4] };
}

/** Model odds for a team with `wins` wins after `week` games (no ties). */
export function getModelOdds(week: number, wins: number): Odds | null {
  const row = MODEL_ODDS[week]?.[wins];
  return row ? tupleToOdds(row) : null;
}

/**
 * Model odds for an arbitrary W-L-T record. A tie counts as half a win: the
 * odds are linearly interpolated between the neighboring all-win/all-loss
 * records at the same number of games played. Returns null when the record is
 * outside the model's range (0 games, or the regular season is over).
 */
export function oddsForRecord(wins: number, losses: number, ties = 0): Odds | null {
  const games = wins + losses + ties;
  if (!MODEL_ODDS[games]) return null;
  const effective = wins + ties / 2;
  const lo = Math.floor(effective);
  const hi = Math.ceil(effective);
  const a = getModelOdds(games, lo);
  const b = getModelOdds(games, hi);
  if (!a || !b) return null;
  const f = effective - lo;
  const out = {} as Odds;
  for (const k of ODDS_OUTCOMES) out[k] = a[k] + (b[k] - a[k]) * f;
  return out;
}

// --- ITTWA history ---

export interface HistoryCell {
  teams: number;
  playoffs: number;
  bye: number;
  semis: number;
  final: number;
  title: number;
}

/** history[week][wins] → how teams with that record after that week finished. */
export type HistoryTable = Record<number, Record<number, HistoryCell>>;

/**
 * Tally, for every completed ITTWA season, each team's record after every
 * regular-season week and how its season ended. Only seasons with a
 * Championship game on the books count (the in-progress season is skipped).
 * Ties (two ever) count as non-wins.
 */
export function computeHistoricalRecordOdds(scores: ScoreRow[]): HistoryTable {
  const bySeason = new Map<string, ScoreRow[]>();
  for (const r of scores) {
    if (!r.season) continue;
    const list = bySeason.get(r.season) ?? [];
    list.push(r);
    bySeason.set(r.season, list);
  }

  const table: HistoryTable = {};
  for (const rows of bySeason.values()) {
    if (!rows.some((r) => r.playoffType === "Championship")) continue;

    const byOwner = new Map<string, ScoreRow[]>();
    for (const r of rows) {
      const list = byOwner.get(r.owner) ?? [];
      list.push(r);
      byOwner.set(r.owner, list);
    }

    for (const ownerRows of byOwner.values()) {
      const playoffRows = ownerRows.filter((r) => r.playoffType);
      const madePlayoffs = playoffRows.length > 0;
      const gotBye = playoffRows.some((r) => r.playoffType === "BYE" || r.opponent === "BYE");
      const finalStanding = ownerRows[0].finalStanding;
      const madeFinal = playoffRows.some((r) => r.playoffType === "Championship");
      const outcome = {
        playoffs: madePlayoffs,
        bye: gotBye,
        // Semifinal losers finish 3rd/4th, so 1–4 = reached the semis.
        semis: madePlayoffs && finalStanding <= 4,
        final: madeFinal,
        title: madeFinal && finalStanding === 1,
      };

      const regular = ownerRows
        .filter((r) => !r.playoffType && (r.points > 0 || r.opponentPoints > 0))
        .sort((a, b) => a.week - b.week);

      let wins = 0;
      regular.forEach((r, i) => {
        if (r.points > r.opponentPoints) wins++;
        const week = i + 1;
        const cell = ((table[week] ??= {})[wins] ??= {
          teams: 0, playoffs: 0, bye: 0, semis: 0, final: 0, title: 0,
        });
        cell.teams++;
        for (const k of ODDS_OUTCOMES) if (outcome[k]) cell[k]++;
      });
    }
  }
  return table;
}

/** "<0.1%" / ">99.9%" style display for model percentages. */
export function formatPct(pct: number): string {
  if (pct <= 0) return "0%";
  if (pct < 0.1) return "<0.1%";
  if (pct >= 100) return "100%";
  if (pct > 99.9) return ">99.9%";
  return `${pct.toFixed(1)}%`;
}
